final class RefundClient {
    private final Http http;
    RefundClient(Http http) { this.http = http; }
    void refund(RefundCommand command) {
        Reply reply = http.post("/refunds", command);
        if (reply.statusCode() < 200 || reply.statusCode() >= 300) {
            throw new TransportException(reply.statusCode());
        }
    }
}

