// Review fixture; checked store contract is specified in docs/cancellation-contract.md.
final class CompensationRunner {
    private final RefundClient refunds;
    private final SagaStore store;
    CompensationRunner(RefundClient refunds, SagaStore store) {
        this.refunds = refunds;
        this.store = store;
    }
    void resume(SagaInstance saga) {
        Claim claim = store.claim(saga.id(), saga.version());
        claim = store.markRefundStarted(claim, saga.refundStepId(), saga.refundCommand());
        refunds.refund(saga.refundCommand());
        claim = store.markRefundCompensated(claim, saga.refundStepId());
        store.markSagaCompensatedIfAllRequiredEffectsResolved(claim);
    }
}
